def main(root):
 sid='src-000320';ss=kb.sources(root);src=next(s for s in ss if s['source_id']==sid);base=root/src['set_path'];doc=base/'documents'/sid;assets=root/'domains/securities/assets'/sid;raw=json.loads((root/'work/documents'/sid/'records.json').read_text(encoding='utf-8'));wr=json.loads((root/'work/docx-render'/sid/'reconciliation.json').read_text(encoding='utf-8'));report=root/'tracking/reviews/fitrr-context-tables-examples.json';tables=[]
 for t,w in zip(raw['tables'],wr['tables']):
  assert t['source_table_id']==w['source_table_id'];num=int(t['source_table_id'][1:]);p=doc/'tables'/(t['table_id']+'.md');m,b=kb.metadata(p);issues={1:['issue-000035'],18:['issue-000032'],26:['issue-000036']}.get(num,[]);a=w['word_start_file_page'];z={3:7,7:9,12:13,27:23,29:25}.get(num,w['word_end_file_page']);m.update(review_status='needs-review' if issues else 'reviewed',visual_review='pass',visual_review_date='2026-11-09',issue_ids=issues,rendered_file_pages=list(range(a,z+1)));b=re.sub(r'Review: row extraction complete.*?(?=\n\n|\Z)','Review: all physical source cells and complete rendered table context directly reconciled.',b,flags=re.S);b=re.sub(r'\n<!-- FITRR-TABLE-REVIEW -->.*','',b,flags=re.S);b+='\n\n<!-- FITRR-TABLE-REVIEW -->\nAll physical rows, headers, blank cells, units/values, role columns and split continuations were compared with Word file pages '+str(a)+'–'+str(z)+' on 2026-11-09. '+kb.link(p,report,'Review evidence')+'. Footnote1 in T11 remains linked through the source linked-notes page. Literal responsibility conflicts remain open where listed.\n';kb.put(p,kb.front(m)+b);tables.append({'source_table_id':t['source_table_id'],'path':p.relative_to(root).as_posix(),'physical_rows':len(t['rows']),'nonempty_cells':w['nonempty_cells'],'automatic_matched_cells':w['matched_nonempty_cells'],'visually_resolved_cells':w['unmatched_cells'],'word_file_pages':[a,z],'transcription_review':'pass','review_status':m['review_status']})
 contextpath=assets/'word-page-context/manifest.json';context=json.loads(contextpath.read_text(encoding='utf-8'));assert len(context['pages'])==59;context.update(visual_review='pass',visual_review_date='2026-11-09',review_scope='All59 complete pages inventoried; all32tables616nonemptycells plus four notation symbols reconciled; all36figure occurrences checked in full Word composition.');kb.dump(contextpath,context)
