 print(json.dumps({'pages':59,'tables':32,'examples':len(examples),'xml_syntax':[x['xml_well_formedness']for x in examples],'schema':[x['schema_validation']for x in examples],'namespace_mismatches':[x['heading_message_id']for x in examples if x.get('heading_namespace_agreement')=='fail']}))
